<?php
namespace App\Policies;
use App\Models\{ConstructionWorkPackage,User}; use App\Policies\Concerns\CompanyOwnedPolicy;
class ConstructionWorkPackagePolicy { use CompanyOwnedPolicy; public function viewAny(User $u):bool{return $this->canForResource($u,'view_any_construction_work_package');} public function view(User $u,ConstructionWorkPackage $r):bool{return $this->canForRecord($u,'view_construction_work_package',$r);} public function create(User $u):bool{return $this->canForResource($u,'create_construction_work_package');} public function update(User $u,ConstructionWorkPackage $r):bool{return in_array($r->status,['planned','in_progress'],true)&&$this->canForRecord($u,'update_construction_work_package',$r);} public function delete(User $u,ConstructionWorkPackage $r):bool{return $r->status==='planned'&&!$r->tasks()->exists()&&!$r->issues()->exists()&&!$r->delays()->exists()&&$this->canForRecord($u,'delete_construction_work_package',$r);} public function start(User $u,ConstructionWorkPackage $r):bool{return $this->canForRecord($u,'start_construction_work_package',$r);} public function complete(User $u,ConstructionWorkPackage $r):bool{return $this->canForRecord($u,'complete_construction_work_package',$r);} public function cancel(User $u,ConstructionWorkPackage $r):bool{return $this->canForRecord($u,'cancel_construction_work_package',$r);} }
